import { ChangeDetectionStrategy, Component, computed, input, output, TemplateRef } from '@angular/core';
import { NzAlertModule } from 'ng-zorro-antd/alert';
import {
  TablerIconComponent,
  IconInfoCircle,
  IconBell,
  IconChecks,
  IconAlertTriangle,
  IconBan,
  IconX,
} from '@tabler/icons-angular';

/** neutral = biến thể xám (chỉ dùng cho appearance 'soft'); default map neutral → 'info'. */
export type HrmAlertType = 'success' | 'info' | 'warning' | 'error' | 'neutral';

/** hrm-alert — mặc định bọc nz-alert (theme token). appearance='soft' = thẻ toast tự dựng (5 tone, icon ô vuông). */
@Component({
  selector: 'hrm-alert',
  imports: [NzAlertModule, TablerIconComponent],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (appearance() === 'soft') {
      <div class="hrm-alert-soft" [attr.data-tone]="type()">
        <span class="ha-ic-box"><tabler-icon [icon]="$any(toneIcon())" [size]="20" /></span>
        <div class="ha-content">
          <div class="ha-message">{{ message() }}</div>
          @if (description()) { <div class="ha-desc">{{ description() }}</div> }
        </div>
        @if (closeable()) {
          <button type="button" class="ha-close" aria-label="close" (click)="close.emit()">
            <tabler-icon [icon]="xIcon" [size]="18" />
          </button>
        }
      </div>
    } @else {
      <nz-alert
        [nzType]="nzType()"
        [nzMessage]="message()"
        [nzDescription]="description() || null"
        [nzShowIcon]="showIcon()"
        [nzCloseable]="closeable()"
        [nzAction]="action()"
        [nzBanner]="banner()"
        (nzOnClose)="close.emit()"></nz-alert>
    }
  `,
  host: { class: 'hrm-alert' },
  styles: [`
:host { display: block; }

/* ── Biến thể soft (toast style) ── */
.hrm-alert-soft {
  display: flex; align-items: flex-start; gap: var(--space-3);
  padding: var(--space-3);
  border-radius: var(--radius-xl);
  border: 1px solid var(--border-sub);
  background: var(--bg-surface-subtle);
}
.ha-ic-box {
  flex: none; width: 40px; height: 40px;
  display: inline-flex; align-items: center; justify-content: center;
  border-radius: var(--radius-md);
  background: var(--bg-surface);
  color: var(--text-sub);
}
.ha-content { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.ha-message { font-size: var(--fs-14); font-weight: 600; color: var(--text-strong); line-height: 1.4; }
.ha-desc {
  font-size: var(--fs-13); color: var(--text-sub); line-height: 1.4;
  /* soft/inline = cảnh báo THƯỜNG TRỰC (vd hộp trong dock, ví dụ styleguide, phụ đề toast)
     → mô tả PHẢI xuống dòng đọc đủ câu, KHÔNG cắt còn 1 dòng + '…'. Nếu ngữ cảnh nào cần
     giới hạn số dòng thì clamp riêng ở outlet đó (vd .hto-card), không áp cho mọi hrm-alert soft. */
  white-space: normal; overflow-wrap: anywhere;
}
.ha-close {
  flex: none; display: inline-flex; align-items: center; justify-content: center;
  padding: 2px; margin: -2px -2px 0 0;
  border: none; background: transparent; cursor: pointer;
  color: var(--text-soft); border-radius: var(--radius-sm);
}
.ha-close:hover { color: var(--text-body); }

/* tone → nền + viền */
.hrm-alert-soft[data-tone='neutral'] { background: var(--bg-surface-subtle); border-color: var(--border-sub); }
.hrm-alert-soft[data-tone='info']    { background: var(--info-bg); border-color: var(--info-border); }
.hrm-alert-soft[data-tone='success'] { background: var(--success-bg); border-color: var(--success-border); }
.hrm-alert-soft[data-tone='warning'] { background: var(--warning-bg); border-color: var(--warning-border); }
.hrm-alert-soft[data-tone='error']   { background: var(--error-bg); border-color: var(--error-border); }

/* tone → màu icon */
.hrm-alert-soft[data-tone='neutral'] .ha-ic-box { color: var(--text-sub); }
.hrm-alert-soft[data-tone='info']    .ha-ic-box { color: var(--info-base); }
.hrm-alert-soft[data-tone='success'] .ha-ic-box { color: var(--success-base); }
.hrm-alert-soft[data-tone='warning'] .ha-ic-box { color: var(--warning-base); }
.hrm-alert-soft[data-tone='error']   .ha-ic-box { color: var(--error-base); }
  `],
})
export class HrmAlert {
  readonly type = input<HrmAlertType>('info');
  readonly message = input('');
  readonly description = input('');
  readonly showIcon = input(true);
  readonly closeable = input(false);
  readonly banner = input(false);
  /** default | soft — 'default' giữ nguyên nz-alert cũ; 'soft' = thẻ toast bám ẢNH 3. */
  readonly appearance = input<'default' | 'soft'>('default');
  /** Nội dung hành động cuối dòng (nút/liên kết) — truyền TemplateRef, mặc định không có. */
  readonly action = input<TemplateRef<void> | null>(null);
  /** Bấm X để đóng (soft: emit khi bấm; default: emit theo nzOnClose). */
  readonly close = output<void>();

  /** nz-alert không hỗ trợ 'neutral' → map về 'info' cho nhánh default. */
  protected readonly nzType = computed<'success' | 'info' | 'warning' | 'error'>(() => {
    const t = this.type();
    return t === 'neutral' ? 'info' : t;
  });

  protected readonly xIcon = IconX;
  private readonly toneIconMap: Record<HrmAlertType, unknown> = {
    neutral: IconInfoCircle,
    info: IconBell,
    success: IconChecks,
    warning: IconAlertTriangle,
    error: IconBan,
  };
  /** Icon theo tone (soft luôn có icon). */
  protected readonly toneIcon = computed(() => this.toneIconMap[this.type()]);
}
